mapper.select:
SELECT sac.id, sac.sku_id, ps.sku_code, ps.name AS sku_name, sac.warehouse_id, w.name AS warehouse_name, sac.low_stock_threshold, sac.out_of_stock_threshold, sac.enabled, sac.remark, sac.created_at, sac.updated_at FROM stock_alert_config sac LEFT JOIN product_sku ps ON sac.sku_id = ps.id AND ps.deleted = 0 LEFT JOIN warehouse w ON sac.warehouse_id = w.id AND w.deleted = 0 WHERE sac.deleted = 0
AND ps.sku_code LIKE CONCAT('%', #{skuCode}, '%')
AND ps.name LIKE CONCAT('%', #{skuName}, '%')
AND sac.warehouse_id = #{warehouseId}
AND sac.enabled = #{enabled}
ORDER BY sac.updated_at DESC

SELECT id, sku_id, warehouse_id, low_stock_threshold, out_of_stock_threshold, enabled, remark, deleted, created_at, updated_at FROM stock_alert_config WHERE sku_id IN
#{skuId}
AND deleted = 0 AND enabled = 1 ORDER BY sku_id, CASE WHEN warehouse_id IS NULL THEN 1 ELSE 0 END

SELECT id, sku_id, warehouse_id, low_stock_threshold, out_of_stock_threshold, enabled, remark, deleted, created_at, updated_at FROM stock_alert_config WHERE sku_id = #{skuId} AND deleted = 0
AND warehouse_id = #{warehouseId}
AND warehouse_id IS NULL
